<div class="dashboard-page-head"><div><p class="eyebrow">AI trading administration</p><h1>AI trading codes</h1><p class="muted">Create global categories priced in USD. Every new category receives 50 unique codes automatically, and another 50 are generated whenever available stock reaches zero.</p></div></div>
<div class="grid two dashboard-split">
<section class="card">
<p class="section-label">Create category</p><h2>New AI trading category</h2>
<form method="post" action="<?= e(route('admin.ai-trading.store')) ?>" class="form-stack"><?= app('csrf')->input() ?>
<label class="field">Category name<input name="name" required placeholder="Beginner"></label>
<label class="field">Description<textarea name="description" rows="4" placeholder="Describe this AI trading category."></textarea></label>
<div class="form-grid"><label class="field">Price in USD<input name="price_usd" inputmode="decimal" required placeholder="100.00"></label><label class="field">Fixed profit %<input name="profit_percent" inputmode="decimal" required placeholder="50"></label></div>
<div class="form-grid"><label class="field">Duration<input name="duration_value" type="number" min="1" required value="30"></label><label class="field">Duration unit<select name="duration_unit"><option value="HOURS">Hours</option><option value="DAYS" selected>Days</option><option value="WEEKS">Weeks</option><option value="MONTHS">Months</option></select></label></div>
